from a_common import P,pt,table,svg,txt,line,box

def build(B):
    c='A1.1'
    water=svg(txt(410,28,'Two water molecules: schematic, not to scale')+txt(200,150,'O δ−',26)+txt(125,230,'H δ+',22)+txt(280,230,'H δ+',22)+line(185,164,137,207,width=4)+line(215,164,265,207,width=4)+txt(490,230,'O δ−',26)+txt(565,150,'H δ+',22)+txt(570,300,'H δ+',22)+line(510,211,551,164,width=4)+line(511,245,552,279,width=4)+line(322,222,442,222,dash=True)+txt(383,202,'X',20)+txt(90,285,'Solid lines: covalent bonds',16,'start')+txt(90,315,'Dashed line: interaction X',16,'start'))
    B.add(c,'sl','Identifying the interaction between water molecules','The schematic shows two water molecules. Which description of X is correct?',correct='A hydrogen bond between a partially positive hydrogen and a partially negative oxygen.',wrong=['A covalent bond that joins the oxygen atoms.','An ionic bond produced by complete transfer of an electron.','A hydrogen bond between two partially negative oxygen atoms.'],why='Unequal electron sharing gives O a partial negative charge and H a partial positive charge; X is an intermolecular attraction between those sites.',diagram=water,statements='A1.1.2')
    B.add(c,'sl','A broken column in a leaf stalk','A researcher introduces an air bubble into a water-filled xylem vessel while its leaf is transpiring. Water transport through this vessel decreases.',[P('Explain how cohesion normally contributes to transport.','Hydrogen bonds create attraction between adjacent water molecules.','This cohesion allows tension generated at the leaf to be transmitted along a continuous water column.'),P('Suggest why the bubble disrupts this process.','The gas gap interrupts the continuous liquid column, reducing transmission of tension through it.')],statements='A1.1.3')
    B.add(c,'sl','Climbing a narrow glass tube','A clean narrow glass tube is placed vertically in water. Water rises above the level in the surrounding beaker.',[P('Distinguish adhesion from cohesion in this observation.','Adhesion is attraction between water and the polar glass surface.','Cohesion is attraction among water molecules, which helps draw further water upward.'),P('Explain why oil coating the glass could reduce the rise.','A non-polar coating reduces favourable interactions between water and the tube surface.')],statements='A1.1.3-4')
    B.add(c,'sl','Surface tension and a floating insect','In a constructed demonstration, identical light wire frames are placed carefully on water. Eight of ten remain at the surface before detergent is added; one of ten remains after detergent is added.',[P('Calculate the decrease in the percentage of frames remaining at the surface.',pt(r'$80\%-10\%=70$ percentage points.','M1')),P('Explain a mechanism consistent with the observation.','Detergent disrupts cohesive interactions at the water surface.','Reduced surface tension provides less support for the frames.'),P('State one limitation of transferring this result directly to live insects.','Insects differ from wire frames in features such as leg contact area or water-repellent surfaces; the model does not reproduce those features.')],data=True,statements='A1.1.3')
    B.add(c,'sl','Transporting solutes in blood','A polar sugar dissolves readily in blood plasma, whereas a large non-polar lipid requires association with transport particles.',[P('Explain the contrast in solubility.','Polar groups on the sugar form favourable interactions, including hydrogen bonds, with water.','The non-polar lipid cannot make equivalent favourable interactions with water and is poorly soluble.'),P('Explain why water is useful as a transport medium.','Dissolved substances can move with the bulk fluid to tissues where they are used.')],statements='A1.1.5')
    B.add(c,'sl','Comparing heating of equal masses',r'Equal masses of water and oil receive the same energy, with negligible energy loss. The water rises by $2.0\,^{\circ}\mathrm C$ and the oil by $4.0\,^{\circ}\mathrm C$. Which conclusion follows?',correct='Water has twice the specific heat capacity of the oil under these conditions.',wrong=['Water has half the specific heat capacity of the oil.','Both liquids have the same specific heat capacity because their masses are equal.','The water received twice as much energy as the oil.'],why=r'For equal energy and mass, $c\propto1/\Delta T$; therefore $c_{water}/c_{oil}=4.0/2.0=2.0$. The greater capacity buffers temperature changes.',statements='A1.1.6')
    B.add(c,'sl','Temperature stability in a pond','A constructed comparison gives daytime and night-time temperatures of a pond and nearby air.'+table(['Environment','Day / °C','Night / °C'],[['Pond',19,16],['Air',25,10]]),[P('Calculate the temperature range in each environment.',r'Pond: $3\,^{\circ}\mathrm C$; air: $15\,^{\circ}\mathrm C$.'),P('Explain one property of water consistent with the smaller range.','Water has a high specific heat capacity, so a relatively large energy transfer is needed for a temperature change.'),P('Explain why these data alone cannot establish that this property is the only cause.','The environments also differ in factors such as mass, mixing, shading and heat exchange, which were not controlled.')],data=True,statements='A1.1.6')
    B.add(c,'sl','A seal in cold water','A ringed seal and a land mammal have similar internal temperatures. Water conducts heat away from a warm surface more effectively than air.',[P('Explain why this creates a challenge for the seal.','A greater rate of heat transfer to the surroundings can cool its body more rapidly.'),P('Explain how a thick layer of blubber helps.','Blubber has low thermal conductivity and increases the distance over which heat must pass.','This reduces heat loss and the energy needed to maintain body temperature.')],statements='A1.1.6')
    B.add(c,'sl','Support and resistance in aquatic habitats','Two aquatic animals are compared: a jellyfish with little rigid support tissue and a rapidly swimming fish with a streamlined shape.',[P('Relate the jellyfish body plan to one physical property of water.','Water provides buoyant support, reducing the need for rigid structures to resist body weight.'),P('Relate streamlining to a different property.','Water is viscous and opposes movement through it.','A streamlined shape reduces drag for a given swimming speed.')],statements='A1.1.6')
    B.add(c,'sl','Why charged particles dissolve','A student draws water around a positive sodium ion. Which orientation is most consistent with the polarity of water?',correct='The oxygen ends of nearby water molecules tend to face the ion.',wrong=['The hydrogen ends tend to face the ion.','The oxygen and hydrogen ends carry equal positive partial charges.','All nearby water molecules split permanently into hydrogen and oxygen gases.'],why='The partially negative oxygen region is attracted to the positive ion. This solvation helps water act as a solvent.',statements='A1.1.2, A1.1.5')
    B.add(c,'sl','Testing the effect of a leaf coating','A student proposes that a wax-like non-polar coating lowers the adhesion of water to a leaf model. They compare the spread area of equal-volume droplets on coated and uncoated glass slides.',[P('Identify the independent variable and a measurement of the dependent variable.','Independent variable: presence or absence of the coating; dependent variable: droplet spread area.'),P('State two controls that improve the comparison.','Keep droplet volume constant.','Use the same glass surface, temperature and time after adding the droplet; credit any one of these in addition to constant volume.'),P('Explain why several droplets should be tested on each treatment.','Replicates reveal variability and reduce the influence of an unusual droplet on the estimated treatment effect.')],statements='A1.1.4')
    B.add(c,'sl','Aqueous reaction compartments','A freshwater unicellular organism contains many dissolved metabolites in its cytoplasm. During severe dehydration, movement of those metabolites and enzyme activity decline.',[P('Explain two roles of water illustrated by the scenario.','Water dissolves many substrates and products, allowing them to be distributed in the cytoplasm.','A fluid medium permits molecular movement and collisions required for metabolic reactions.')],statements='A1.1.1, A1.1.5')
    B.add(c,'ahl','Water delivery to a young planet',r'A constructed model estimates that impacts delivered $8.0\times10^{18}\,\mathrm{kg}$ of asteroid material. The material was $12\%$ water by mass, and $25\%$ of the delivered water was retained.',[P('Calculate the mass of water retained.',pt(r'$8.0\times10^{18}\times0.12\times0.25$.','M1'),r'$2.4\times10^{17}\,\mathrm{kg}$.'),P('Explain why this calculation does not prove that asteroids supplied all water on that planet.','The result depends on assumed impact mass, water fraction and retention; it neither measures every source nor excludes other sources.')],data=True,statements='A1.1.7')
    B.add(c,'ahl','Retaining water after an impact','Two hypothetical rocky planets receive similar water deliveries. One has much weaker gravity and a persistently hotter surface.',[P('Explain two reasons why this planet may retain less water.','Weaker gravity makes escape of water or its components to space easier.','High temperature keeps more water as vapour and may prevent its long-term condensation into surface reservoirs.')],statements='A1.1.7')
    B.add(c,'ahl','Interpreting a habitable orbital zone','An exoplanet lies within a star’s estimated habitable zone. Which conclusion is justified?',correct='Its orbital position may permit surface liquid water under suitable atmospheric conditions.',wrong=['Living cells must already be present.','Its atmosphere must contain exactly the same gases as Earth.','Its oceans must have the same salinity as Earth’s oceans.'],why='The zone concerns conditions compatible with liquid water, not proof of water, an Earth-like atmosphere or life.',statements='A1.1.8')
    B.add(c,'ahl','Selecting a follow-up observation','Constructed observations describe planet P with a temperature compatible with liquid water but unknown atmosphere, and planet Q with spectral evidence of water vapour but a very hot surface.',[P('Evaluate whether either observation alone establishes habitability.','P’s temperature is compatible with liquid water, but atmospheric pressure/composition and water availability are unknown.','Water vapour at Q does not establish that stable surface liquid water exists.'),P('Suggest one further measurement and explain its value.','Measure atmospheric pressure/composition or surface-temperature variation to constrain whether water could remain liquid; credit another relevant measurement with its link.')],data=True,statements='A1.1.7-8')

    c='A1.2'
    B.add(c,'sl','Reading a nucleotide model','A model labels a phosphate group P, a pentose sugar S and a nitrogenous base B. Which arrangement correctly represents one nucleotide?',correct='The phosphate and the base are each attached to the sugar.',wrong=['The sugar and phosphate are each attached only to the base.','The base is a protein surrounding the phosphate.','The phosphate is attached to two separate bases, with no sugar.'],why='A nucleotide contains one sugar with an attached nitrogenous base and phosphate group.',statements='A1.2.2')
    B.add(c,'sl','Two kinds of linkage in DNA','A DNA sample is heated enough to separate its two strands while each strand remains a long polymer.',[P('Distinguish the interactions disrupted from those retained.','Hydrogen bonds between complementary bases on opposite strands are disrupted.','Covalent linkages in each sugar-phosphate backbone remain intact.'),P('Explain why separated strands can pair again on cooling.','Complementary bases can reform hydrogen bonds when suitable bases align.')],statements='A1.2.3, A1.2.6, A1.2.8')
    B.add(c,'sl','A complementary sequence','One DNA strand contains the sequence A–G–T–C–C–A. Write the sequence on the complementary strand directly opposite it, reading in the same left-to-right direction on the page.',[P('Deduce the complementary sequence.','T–C–A–G–G–T.'),P('Explain why complementarity helps copying.','Each base on a template specifies which complementary nucleotide should pair with it, preserving sequence information.')],statements='A1.2.6, A1.2.8')
    B.add(c,'sl','Recognizing RNA in a sample','A nucleic acid contains ribose and uracil and is mainly single-stranded. Which identification is best supported?',correct='RNA.',wrong=['DNA, because all nucleic acids contain uracil.','A protein, because ribose is an amino acid.','A phospholipid, because it contains phosphate.'],why='Ribose, uracil and a usually single-stranded chain are characteristic of RNA; DNA normally contains deoxyribose and thymine.',statements='A1.2.4-7')
    B.add(c,'sl','Building a linear RNA strand','A model assembles a single unbranched RNA chain of 25 nucleotides. Each new connection is represented as one condensation reaction.',[P('Determine the number of connections between adjacent nucleotides.','There are $25-1=24$ connections.'),P('State what is removed in the simplified condensation model.','One water molecule is removed per connection, giving 24 water molecules in this model.')],statements='A1.2.5',notes='A simplified monomer condensation model is explicitly stated; this is not a claim about the full enzymatic nucleotide-triphosphate mechanism in cells.')
    B.add(c,'sl','Base composition in double-stranded DNA',r'In a constructed double-stranded DNA sample, adenine forms $22\%$ of all bases.',[P('Calculate the percentage of thymine and of guanine.',r'Thymine is $22\%$ because A pairs with T.',r'Guanine is $(100-44)/2=28\%$ because the remaining bases are equal amounts of G and C.'),P('Explain why the same deduction need not work for a single-stranded RNA sample.','A single RNA strand does not necessarily have a complementary partner imposing equal total A/U or G/C proportions.')],data=True,statements='A1.2.6-8',notes='Arithmetic follows shared complementary pairing; it does not require historical Chargaff evidence, which is AHL.')
    B.add(c,'sl','Comparing two pentose sugars','Ribose and deoxyribose each contain five carbon atoms. In deoxyribose, the group at carbon 2 differs from ribose.',[P('State the difference at carbon 2.','Ribose has an OH group where deoxyribose has H.'),P('Identify the nucleic acid normally associated with each sugar.','RNA contains ribose, whereas DNA contains deoxyribose.')],statements='A1.2.7')
    B.add(c,'sl','Information in a short sequence','A synthetic single DNA strand has eight positions, each of which can contain A, T, G or C. Assume no restrictions on sequence.',[P('Calculate the number of distinct sequences.',pt(r'$4^8$.','M1'),'65,536 sequences.'),P('Explain why doubling the sequence length more than doubles the information-bearing possibilities.','Each added position multiplies the number of possible sequences by four, so the number grows exponentially with length.')],statements='A1.2.9')
    B.add(c,'sl','A shared translation rule','A researcher finds that the same mRNA codon specifies the same amino acid in two distantly related organisms. The result fits the broad conservation of the genetic code.',[P('Explain how this supports common ancestry.','A shared coding system can have been inherited from a common ancestor.','Conservation across distantly related groups is consistent with an ancient origin of that system.'),P('State why one matching codon alone is limited evidence.','A single match is a small sample; comparison across many codons and independent biological features gives stronger support.')],statements='A1.2.10')
    B.add(c,'sl','Correcting a DNA model','A student’s model has A paired with C, G paired with T and a sugar-phosphate backbone made of weak hydrogen bonds.',[P('Correct both base-pairing errors.','A pairs with T; G pairs with C.'),P('Correct the backbone description and state where hydrogen bonds belong.','The sugar-phosphate backbone contains covalent bonds.','Hydrogen bonds connect complementary bases across the two strands.')],statements='A1.2.3-6')
    B.add(c,'ahl','Writing an antiparallel strand',r'A DNA strand is written $5^{\prime}$–A–C–G–T–T–A–$3^{\prime}$. A researcher wants the complementary strand written from its own $5^{\prime}$ end to its own $3^{\prime}$ end.',[P('Determine the required sequence, including end labels.',r'$5^{\prime}$–T–A–A–C–G–T–$3^{\prime}$.'),P('Explain why reversing the left-to-right order is necessary.',r'The complementary strand runs antiparallel to the original, so its $5^{\prime}$ end is opposite the original $3^{\prime}$ end.')],statements='A1.2.11')
    B.add(c,'ahl','Keeping a constant helix width','A model DNA duplex has pairs of one two-ring base and one one-ring base. A proposed alternative pairs two two-ring bases together.',[P('Identify the two base categories.','Two-ring bases are purines; one-ring bases are pyrimidines.'),P('Explain why normal complementary pairs help keep the helix width constant.','Each normal pair contains one purine and one pyrimidine and therefore has a similar overall width.','A purine–purine pair is wider and would distort the regular helix.')],statements='A1.2.12')
    B.add(c,'ahl','Distinguishing nucleosome components','In an idealized chromatin segment, 12 complete nucleosome core particles are present. Ignore any histone loss or exchange.',[P('Calculate the number of core histone proteins.',r'Each core contains eight histones, so $12\times8=96$ core histones.'),P('Explain why this is not necessarily the total number of histone molecules associated with the segment.','Additional linker histones can associate with linker DNA outside the eight-protein cores.'),P('Describe the relationship of DNA to each core.','DNA is wrapped around the histone core rather than being replaced by protein.')],statements='A1.2.13')
    B.add(c,'ahl','Tracing material entering bacteria','Constructed data from an experiment inspired by bacteriophage tracer studies are shown. Label P is attached to phage DNA; label S is attached to phage protein. After infection, blending and centrifugation, the bacteria form a pellet.'+table(['Label','Recovered label in pellet / %','Recovered label in supernatant / %'],[['P',82,18],['S',12,88]]),[P('Identify which phage component mainly entered the bacteria and cite the evidence.','DNA mainly entered: 82% of its P label was in the bacterial pellet, compared with 12% of the protein S label.'),P('Explain how the result supports DNA as genetic material.','The component entering cells is the candidate carrying instructions for production of new phages; DNA enters far more than protein.'),P('Give one reason the result is evidence rather than absolute proof.','Incomplete separation, residual attached phage or tracer contamination could account for some label in the unexpected fraction; further controls/replication are needed.')],data=True,statements='A1.2.14')
    B.add(c,'ahl','Testing a repeating-base hypothesis','A proposed model claims that every DNA molecule consists of equal proportions of A, T, G and C. Constructed analyses of two double-stranded samples give: sample X, A30%,T30%,G20%,C20%; sample Y, A18%,T18%,G32%,C32%.',[P('Evaluate the proposed model using these results.','Both samples depart from 25% of each base, contradicting the equal-proportion prediction.','The samples still satisfy A=T and G=C, which is consistent with complementary pairing.'),P('Explain the distinction between rejecting this model and proving a replacement model.','A failed necessary prediction can falsify the proposed model; agreement with some predictions supports a replacement but does not prove all its claims.')],data=True,statements='A1.2.15')
    B.add(c,'ahl','Choosing a tracer control','In a phage experiment, a researcher concludes that pellet radioactivity represents material inside bacterial cells. Which control most directly tests whether phages merely sticking outside the cells explain that signal?',correct='Measure pellet radioactivity after a treatment that removes externally attached phages without lysing the bacteria.',wrong=['Use a longer exposure of the photographic film without changing the sample.','Measure total phage DNA without separating material attached to cells from material inside them.','Discard the supernatant before measuring the pellet.'],why='Removing external phage material while preserving intact bacteria separates surface association from entry into the cells.',statements='A1.2.14')
